begin;
set local search_path=public,extensions;
select plan(32);
select is((select course_id||'/'||content_version||'/'||schema_version from public.studio_foundation_lessons where id='apis-data-v1'),'system-design-studio-v1/apis-data-content-v1/api-position-v1','New lesson pins its own published identities');
select ok(not has_table_privilege('authenticated','learning_private.foundation_answer_keys','SELECT'),'API keys stay private');
select ok(not has_table_privilege('authenticated','public.studio_foundation_positions','INSERT'),'No direct position insert');
select ok(not has_table_privilege('authenticated','public.studio_foundation_events','UPDATE'),'No client grade update');
insert into auth.users(id,email) values('a4624000-0000-0000-0000-000000000001','api-policy-a@example.test'),('a4624000-0000-0000-0000-000000000002','api-policy-b@example.test');
update public.profiles set goal='Learn API contracts' where user_id in ('a4624000-0000-0000-0000-000000000001','a4624000-0000-0000-0000-000000000002');
set local role anon;
select throws_ok($$select public.get_studio_foundation('system-design-studio-v1','apis-data-v1')$$,'42501','permission denied for function get_studio_foundation','Anonymous API lesson read denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a4624000-0000-0000-0000-000000000001',true);
select is(public.get_studio_foundation('system-design-studio-v1','apis-data-v1')->>'enrolled','false','Existing course enrolment required');
select throws_ok($$select public.save_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1',0,'a4624000-0000-0000-0000-000000000003','{"section":"learn","step":0,"viewed":false,"explorer":{"scenario":"create","eventId":"evt_999","title":""}}'::jsonb)$$,'42501','Enrol in System Design Studio first','Unenrolled save denied');
select lives_ok($$select public.enrol_course('system-design-studio-v1')$$,'One shared Studio enrolment');
select is(jsonb_array_length(public.get_studio_foundation('system-design-studio-v1','apis-data-v1')->'evidence')::text,'0','No initial hints or answers');
select throws_ok($$select public.save_studio_foundation('apis-data-v1','web-request-content-v1','api-position-v1',0,'a4624000-0000-0000-0000-000000000003','{"section":"learn","step":0,"viewed":false,"explorer":{"scenario":"create","eventId":"evt_999","title":""}}'::jsonb)$$,'22023','Unsupported lesson version','Content cannot cross lessons');
select throws_ok($$select public.save_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1',0,'a4624000-0000-0000-0000-000000000003','{"section":"learn","step":0,"viewed":false}'::jsonb)$$,'22023','Invalid API lesson position','Old position shape is not accepted for this lesson');
select throws_ok($$select public.save_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1',0,'a4624000-0000-0000-0000-000000000003','{"section":"learn","step":0,"viewed":false,"explorer":{"scenario":"create","eventId":"evt_999","title":"","correct":true}}'::jsonb)$$,'22023','Invalid explorer configuration','Explorer cannot carry a grade');
select is(public.save_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1',0,'a4624000-0000-0000-0000-000000000003','{"section":"learn","step":0,"viewed":false,"explorer":{"scenario":"create","eventId":"evt_999","title":""}}'::jsonb)->>'revision','1','Explicit save retains even invalid-input draft');
select is(public.save_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1',0,'a4624000-0000-0000-0000-000000000003','{"section":"learn","step":0,"viewed":false,"explorer":{"scenario":"create","eventId":"evt_999","title":""}}'::jsonb)->>'revision','1','Identical position retries save once');
select throws_ok($$select public.save_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1',0,gen_random_uuid(),'{"section":"learn","step":0,"viewed":false,"explorer":{"scenario":"create","eventId":"evt_999","title":""}}'::jsonb)$$,'40001','A newer lesson position exists','Stale position cannot overwrite');
select throws_ok($$select public.save_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1',0,'a4624000-0000-0000-0000-000000000003','{"section":"recap","step":0,"viewed":false,"explorer":{"scenario":"create","eventId":"evt_999","title":""}}'::jsonb)$$,'22023','Request already used for different work','Conflicting key cannot replace payload');
select throws_ok($$select public.submit_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1','initiator','attempt','browser','a4624000-0000-0000-0000-000000000004')$$,'22023','Invalid practice event','Questions cannot cross lessons');
select throws_ok($$select public.submit_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1','api-read-one','hint',null,'a4624000-0000-0000-0000-000000000004')$$,'22023','Try the question before requesting help','No hint before trying');
select is(public.submit_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1','api-read-one','attempt','post-list','a4624000-0000-0000-0000-000000000004')->>'correct','false','Private key evaluates incorrect answer');
select is(public.submit_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1','api-read-one','attempt','post-list','a4624000-0000-0000-0000-000000000004')->>'attempt','1','Identical answer retry keeps attempt number');
select throws_ok($$select public.submit_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1','api-read-one','attempt','get-one','a4624000-0000-0000-0000-000000000004')$$,'22023','Request already used for different work','Conflicting attempt key rejected');
select is(public.submit_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1','api-read-one','hint',null,gen_random_uuid())->>'hintLevel','1','Progressive hint evidence stored');
select is(public.submit_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1','api-read-one','attempt','get-one',gen_random_uuid())->>'independent','false','Later correct answer remains a retry');
select is(public.submit_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1','api-create-body','attempt','title',gen_random_uuid())->>'correct','true','Server evaluates api-create-body');
select is(public.submit_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1','api-error-kind','attempt','missing-invalid',gen_random_uuid())->>'correct','true','Server evaluates api-error-kind');
select is(public.submit_studio_foundation('apis-data-v1','apis-data-content-v1','api-position-v1','api-representation','attempt','chosen-view',gen_random_uuid())->>'correct','true','Server evaluates api-representation');
select is(jsonb_array_length(public.export_learner_data()->'studio_foundation_positions')::text,'1','API draft included in owner export');
select is(jsonb_array_length(public.export_learner_data()->'studio_foundation_events')::text,'6','All attempts and help included in owner export');
select set_config('request.jwt.claim.sub','a4624000-0000-0000-0000-000000000002',true);
select is((select count(*)::text from public.studio_foundation_positions),'0','Other learner cannot read API draft');
select is((select count(*)::text from public.studio_foundation_events),'0','Other learner cannot read API evidence');
reset role;
delete from auth.users where id='a4624000-0000-0000-0000-000000000001';
select is((select count(*)::text from public.studio_foundation_positions where user_id='a4624000-0000-0000-0000-000000000001'),'0','Synthetic Auth deletion cascades API draft');
select is((select count(*)::text from public.studio_foundation_events where user_id='a4624000-0000-0000-0000-000000000001'),'0','Synthetic Auth deletion cascades API evidence');
select * from finish();
rollback;
